using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests
{
    public static class TestHelpers
    {
        public static SchoolContext CreateInMemoryContext(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }

        public static void SeedStudents(SchoolContext context)
        {
            context.Students.AddRange(
                new Student { ID = 1, FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = DateTime.Parse("2020-09-01") },
                new Student { ID = 2, FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = DateTime.Parse("2021-09-01") },
                new Student { ID = 3, FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = DateTime.Parse("2022-09-01") }
            );
            context.SaveChanges();
        }

        public static void SeedInstructors(SchoolContext context)
        {
            context.Instructors.AddRange(
                new Instructor { ID = 10, FirstMidName = "Kim", LastName = "Abercrombie", HireDate = DateTime.Parse("1995-03-11") },
                new Instructor { ID = 11, FirstMidName = "Fadi", LastName = "Fakhouri", HireDate = DateTime.Parse("2002-07-06") }
            );
            context.SaveChanges();
        }

        public static void SeedDepartments(SchoolContext context)
        {
            SeedInstructors(context);
            context.Departments.AddRange(
                new Department { DepartmentID = 1, Name = "English", Budget = 350000, StartDate = DateTime.Parse("2007-09-01"), InstructorID = 10 },
                new Department { DepartmentID = 2, Name = "Mathematics", Budget = 100000, StartDate = DateTime.Parse("2007-09-01"), InstructorID = 11 }
            );
            context.SaveChanges();
        }

        public static void SeedCourses(SchoolContext context)
        {
            SeedDepartments(context);
            context.Courses.AddRange(
                new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 },
                new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = 2 }
            );
            context.SaveChanges();
        }

        public static void SeedFullData(SchoolContext context)
        {
            SeedCourses(context);
            SeedStudents(context);

            context.Enrollments.AddRange(
                new Enrollment { EnrollmentID = 1, StudentID = 1, CourseID = 1050, Grade = Grade.A },
                new Enrollment { EnrollmentID = 2, StudentID = 1, CourseID = 4022, Grade = Grade.C },
                new Enrollment { EnrollmentID = 3, StudentID = 2, CourseID = 1050, Grade = Grade.B }
            );
            context.SaveChanges();
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut = new();

        public void Dispose() => _sut.Dispose();

        [Fact]
        public void SendNotification_WithDisplayName_EnqueuesNotification()
        {
            _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "admin");

            var received = _sut.ReceiveNotification();

            Assert.NotNull(received);
            Assert.Equal("Student", received.EntityType);
            Assert.Equal("42", received.EntityId);
            Assert.Equal("CREATE", received.Operation);
            Assert.Contains("John Doe", received.Message);
            Assert.Contains("created", received.Message);
            Assert.Equal("admin", received.CreatedBy);
            Assert.False(received.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
        {
            _sut.SendNotification("Course", "101", EntityOperation.UPDATE);

            var received = _sut.ReceiveNotification();

            Assert.NotNull(received);
            Assert.Contains("ID: 101", received.Message);
            Assert.Contains("updated", received.Message);
            Assert.Equal("System", received.CreatedBy);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "created")]
        [InlineData(EntityOperation.UPDATE, "updated")]
        [InlineData(EntityOperation.DELETE, "deleted")]
        public void SendNotification_GeneratesCorrectMessage_ForEachOperation(EntityOperation op, string expectedVerb)
        {
            _sut.SendNotification("Dept", "1", "Science", op);

            var received = _sut.ReceiveNotification();

            Assert.NotNull(received);
            Assert.Contains(expectedVerb, received.Message);
            Assert.Equal(op.ToString(), received.Operation);
        }

        [Fact]
        public void ReceiveNotification_ReturnsNull_WhenQueueIsEmpty()
        {
            var result = _sut.ReceiveNotification();
            Assert.Null(result);
        }

        [Fact]
        public void SendAndReceive_MultipleNotifications_DequeuesInOrder()
        {
            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();

            Assert.Equal("A", first!.EntityType);
            Assert.Equal("B", second!.EntityType);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op, but should not throw
            var ex = Record.Exception(() => _sut.MarkAsRead(999));
            Assert.Null(ex);
        }

        [Fact]
        public void SendNotification_WithNullUserName_DefaultsToSystem()
        {
            _sut.SendNotification("X", "1", "Name", EntityOperation.CREATE, null);

            var received = _sut.ReceiveNotification();
            Assert.Equal("System", received!.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToNonDefault()
        {
            _sut.SendNotification("X", "1", EntityOperation.CREATE);

            var received = _sut.ReceiveNotification();
            Assert.NotEqual(default, received!.CreatedAt);
        }
    }
}

using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_FirstPage_ContainsCorrectItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.First());
            Assert.Equal(10, result.Last());
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
        }

        [Fact]
        public void Create_SecondPage_SkipsFirstPageItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(11, result.First());
            Assert.Equal(20, result.Last());
            Assert.Equal(2, result.PageIndex);
        }

        [Fact]
        public void Create_LastPage_ContainsRemainingItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(21, result.First());
        }

        [Theory]
        [InlineData(1, false, true)]   // first page: no prev, has next
        [InlineData(2, true, true)]    // middle page: has both
        [InlineData(3, true, false)]   // last page: has prev, no next
        public void HasPreviousPage_HasNextPage_ReflectPosition(int pageIndex, bool expectPrev, bool expectNext)
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex, pageSize: 10);

            Assert.Equal(expectPrev, result.HasPreviousPage);
            Assert.Equal(expectNext, result.HasNextPage);
        }

        [Fact]
        public void Create_SinglePage_HasNoPrevOrNext()
        {
            var source = Enumerable.Range(1, 5).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var source = Enumerable.Empty<int>().AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
        }

        [Fact]
        public void TotalPages_RoundsUp_WhenNotEvenlyDivisible()
        {
            var source = Enumerable.Range(1, 11).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Equal(2, result.TotalPages);
        }
    }
}

