        {
            using var context = TestHelpers.CreateInMemoryContext();

            DbInitializer.Initialize(context);
            var studentCountFirst = context.Students.Count();

            DbInitializer.Initialize(context);
            var studentCountSecond = context.Students.Count();

            Assert.Equal(studentCountFirst, studentCountSecond);
        }

        [Fact]
