using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_FirstPage_ContainsCorrectItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.First());
            Assert.Equal(10, result.Last());
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
        }

        [Fact]
        public void Create_SecondPage_SkipsFirstPageItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(11, result.First());
            Assert.Equal(20, result.Last());
            Assert.Equal(2, result.PageIndex);
        }

        [Fact]
        public void Create_LastPage_ContainsRemainingItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(21, result.First());
        }

        [Theory]
        [InlineData(1, false, true)]   // first page: no prev, has next
        [InlineData(2, true, true)]    // middle page: has both
        [InlineData(3, true, false)]   // last page: has prev, no next
        public void HasPreviousPage_HasNextPage_ReflectPosition(int pageIndex, bool expectPrev, bool expectNext)
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex, pageSize: 10);

            Assert.Equal(expectPrev, result.HasPreviousPage);
            Assert.Equal(expectNext, result.HasNextPage);
        }

        [Fact]
        public void Create_SinglePage_HasNoPrevOrNext()
        {
            var source = Enumerable.Range(1, 5).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var source = Enumerable.Empty<int>().AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
        }

        [Fact]
        public void TotalPages_RoundsUp_WhenNotEvenlyDivisible()
        {
            var source = Enumerable.Range(1, 11).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Equal(2, result.TotalPages);
        }
    }
}

