using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestHelpers.CreateInMemoryContext();
            _controller = new NotificationsController(_context);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_ReturnsJsonWithSuccessFlag()
        {
            var result = _controller.GetNotifications();

            Assert.NotNull(result);
            Assert.NotNull(result.Value);
            var value = result.Value;
            // Access the anonymous type properties via reflection
            var successProp = value.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(value)!);
        }

        [Fact]
        public void GetNotifications_AfterSending_ReturnsNotifications()
        {
            // Use the controller's inherited notificationService to send a notification
            // We can test the round-trip by sending via another controller instance
            var studentCtx = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(studentCtx);
            var studentController = new StudentsController(studentCtx);
            studentController.ControllerContext = new ControllerContext { HttpContext = new DefaultHttpContext() };
            studentController.TempData = new Microsoft.AspNetCore.Mvc.ViewFeatures.TempDataDictionary(
                studentController.ControllerContext.HttpContext, new TestTempDataProvider());

            // Create a student to trigger notification
            var student = new Models.Student
            {
                FirstMidName = "Test",
                LastName = "Notify",
                EnrollmentDate = DateTime.Parse("2023-09-01")
            };
            studentController.Create(student);

            // Now retrieve notifications
            var result = _controller.GetNotifications();
            Assert.NotNull(result.Value);

            studentController.Dispose();
            studentCtx.Dispose();
        }

        [Fact]
        public void MarkAsRead_ReturnsJsonWithSuccess()
        {
            var result = _controller.MarkAsRead(1);

            Assert.NotNull(result);
            var value = result.Value;
            var successProp = value!.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value)!);
        }

        [Fact]
        public void Index_ReturnsView()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }
    }
}

