namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests
    {
        [Fact]
        public void Context_CanAddAndRetrieveStudents()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2023-09-01")
            };

            context.Students.Add(student);
            context.SaveChanges();

            var retrieved = context.Students.Single();
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal("Student", retrieved.LastName);
        }

        [Fact]
        public void Context_CanAddAndRetrieveCourses()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            context.Departments.Add(new Department
            {
                DepartmentID = 1,
                Name = "TestDept",
                Budget = 100000,
                StartDate = DateTime.Now
            });
            context.SaveChanges();

            var course = new Course
            {
                CourseID = 1001,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = 1
            };
            context.Courses.Add(course);
            context.SaveChanges();

            var retrieved = context.Courses.Single();
            Assert.Equal("Test Course", retrieved.Title);
            Assert.Equal(3, retrieved.Credits);
        }

        [Fact]
        public void Context_CourseAssignment_HasCompositeKey()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedCourses(context);

            var assignment = new CourseAssignment { CourseID = 1050, InstructorID = 10 };
            context.CourseAssignments.Add(assignment);
            context.SaveChanges();

            var retrieved = context.CourseAssignments.Find(1050, 10);
            Assert.NotNull(retrieved);
        }

        [Fact]
        public void Context_CanAddEnrollments()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedFullData(context);

            Assert.Equal(3, context.Enrollments.Count());
        }

        [Fact]
        public void Context_CanAddOfficeAssignment()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedInstructors(context);

            context.OfficeAssignments.Add(new OfficeAssignment
            {
                InstructorID = 10,
                Location = "Room 101"
            });
            context.SaveChanges();

            var office = context.OfficeAssignments.Find(10);
            Assert.NotNull(office);
            Assert.Equal("Room 101", office.Location);
        }

        [Fact]
        public void Context_PersonFullName_ReturnsLastCommaFirst()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var student = new Student
            {
                FirstMidName = "John",
                LastName = "Doe",
                EnrollmentDate = DateTime.Now
            };
            context.Students.Add(student);
            context.SaveChanges();

            var retrieved = context.Students.Single();
            Assert.Equal("Doe, John", retrieved.FullName);
        }

        [Fact]
        public void Context_Notification_CanBeStored()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test",
                CreatedAt = DateTime.Now,
                IsRead = false
            };
            context.Notifications.Add(notification);
            context.SaveChanges();

            Assert.Single(context.Notifications);
        }
    }
}
